"use client";
import { useState } from "react";
import "./InterestRate.css";
import { FaFilePdf, FaDownload, FaCalendarAlt } from "react-icons/fa";

export default function InterestRate() {
  const currentRates = {
    effectiveDate: "2080/04/07",
    savings: [
      { name: "Group Saving", rate: "7.5%" },
      { name: "Personal Saving", rate: "7.5%" },
      { name: "Pension/Child Saving", rate: "9.0%" },
    ],
    loans: [
      { name: "General Loan", rate: "15.0%" },
      { name: "Micro-Enterprise Loan", rate: "15.0%" },
    ],
  };

  const pdfArchive = [
    { year: "2082/83", months: ["Chaitra", "Falgun", "Magh", "Poush", "Mangsir"] },
    { year: "2081/82", months: ["Full Year Archive"] },
    { year: "2080/81", months: ["Full Year Archive"] },
  ];

  const [selectedYear, setSelectedYear] = useState(pdfArchive[0].year);

  const activeYearData = pdfArchive.find((a) => a.year === selectedYear);

  return (
    <div className="min-h-screen bg-slate-50">
      {/* HEADER */}
      <div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white p-8">
        <h1 className="text-3xl font-bold">Rates & Charges</h1>
        <p className="opacity-90">Transparent and regulated financial services</p>
      </div>

      <div className="max-w-7xl mx-auto p-6 grid md:grid-cols-4 gap-6">
        
        {/* SIDEBAR */}
        <aside className="bg-white rounded-2xl shadow-sm p-5">
          <h3 className="flex items-center gap-2 font-semibold mb-4">
            <FaCalendarAlt /> Archive
          </h3>

          <div className="space-y-2">
            {pdfArchive.map((item) => (
              <button
                key={item.year}
                onClick={() => setSelectedYear(item.year)}
                className={`w-full text-left px-4 py-2 rounded-lg transition 
                ${
                  selectedYear === item.year
                    ? "bg-blue-600 text-white"
                    : "hover:bg-gray-100"
                }`}
              >
                F.Y. {item.year}
              </button>
            ))}
          </div>
        </aside>

        {/* MAIN CONTENT */}
        <main className="md:col-span-3 space-y-6">
          
          {/* SUMMARY CARDS */}
          <div className="grid sm:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm">
              <p className="text-gray-500">Savings Interest (Max)</p>
              <h2 className="text-3xl font-bold text-green-600">9.0%</h2>
              <p className="text-sm text-gray-400 mt-2">
                Effective: {currentRates.effectiveDate}
              </p>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm">
              <p className="text-gray-500">Loan Interest (Max)</p>
              <h2 className="text-3xl font-bold text-red-500">15.0%</h2>
              <p className="text-sm text-gray-400 mt-2">
                Effective: {currentRates.effectiveDate}
              </p>
            </div>
          </div>

          {/* DETAILED TABLE */}
          <div className="bg-white rounded-2xl shadow-sm p-6">
            <h3 className="font-semibold mb-4">Detailed Interest Breakdown</h3>

            <div className="grid md:grid-cols-2 gap-6">
              {/* Savings */}
              <div>
                <h4 className="font-medium mb-2 text-blue-600">Savings</h4>
                <ul className="space-y-2">
                  {currentRates.savings.map((item, i) => (
                    <li
                      key={i}
                      className="flex justify-between bg-gray-50 p-3 rounded-lg"
                    >
                      <span>{item.name}</span>
                      <span className="font-semibold">{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {/* Loans */}
              <div>
                <h4 className="font-medium mb-2 text-red-500">Loans</h4>
                <ul className="space-y-2">
                  {currentRates.loans.map((item, i) => (
                    <li
                      key={i}
                      className="flex justify-between bg-gray-50 p-3 rounded-lg"
                    >
                      <span>{item.name}</span>
                      <span className="font-semibold">{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>

          {/* PDF DOWNLOAD SECTION */}
          <div className="bg-white rounded-2xl shadow-sm p-6">
            <h3 className="font-semibold mb-4">
              Interest Rate Notices ({selectedYear})
            </h3>

            <div className="grid sm:grid-cols-2 gap-4">
              {activeYearData.months.map((month, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-4 border rounded-xl hover:shadow-md transition"
                >
                  <div className="flex items-center gap-3">
                    <FaFilePdf className="text-red-500 text-xl" />
                    <span className="text-sm font-medium">
                      {month}
                    </span>
                  </div>

                  <a
                    href={`/assets/pdf/interest/rate-${selectedYear.replace(
                      "/",
                      "-"
                    )}-${month.toLowerCase()}.pdf`}
                    target="_blank"
                    rel="noreferrer"
                    className="flex items-center gap-2 text-blue-600 hover:underline"
                  >
                    <FaDownload />
                    Download
                  </a>
                </div>
              ))}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
